given.script:
%dw 2.0
output application/json
---
payload.orders
  map ((o) -> do {
    var match = (payload.customers filter ($.id == o.customerId))[0]
    ---
    { orderId: o.orderId, customerId: o.customerId, customerName: match.name }
  })
  filter ($.customerName != null)

